//! 🎟️ One Source owns encoding, donor, whole VM replies and frozen output until paid handback.
use super::{SourceJsonEncoder,GuestRelayOutputHome};
use semio_plugin_host_guest_runtime::{GuestRuntimes,GuestInstance,OwnedOriginalCallProgress,OwnedOriginalCallStatus};
use semio_framework_actor::{OriginalGuestExecutionBudget,OriginalGuestExecutionReceipt};
use semio_framework_job::{StepContext,OriginalTurnFailure,OriginalSourceBinding};
use semio_framework_value::{RetainedCloneProgress,RetainedWorkOutcome,ValueError,ValueRefusalKind,retirement::controlled::ControlledRetirement};
use std::mem::{ManuallyDrop,size_of};

#[derive(Clone,Copy,PartialEq,Eq)]
enum Phase{Encode,EncoderClose,Begin,Drive,AwaitBudget,Output,Acknowledge,Release,DonorClose,Complete,Closing}
#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub enum GuestRelayUnitStatus{Pending,AwaitBudget,Output,Complete,Refused}
pub struct GuestRelayUnitFlow{binding:Option<OriginalSourceBinding>,prepared:Option<u64>,encoder:SourceJsonEncoder,input:ManuallyDrop<Option<Vec<u8>>>,input_close:Option<ControlledRetirement<Vec<u8>>>,phase:Phase,progress:ManuallyDrop<Option<OwnedOriginalCallProgress>>,failure:ManuallyDrop<Option<OriginalTurnFailure>>,failure_close:Option<ControlledRetirement<OriginalTurnFailure>>,cursor:usize}
fn refused()->ValueError{ValueError::literal(ValueRefusalKind::OwnershipLimit,"original unit flow differs from its retained producer")}
fn metadata(cx:&mut StepContext<'_>,retiring:bool)->Result<bool,OriginalTurnFailure>{let g=cx.retained_grant();let bytes=size_of::<Phase>()+size_of::<Option<OwnedOriginalCallProgress>>()+size_of::<Option<OriginalSourceBinding>>();if (if retiring{cx.retirement_should_yield()}else{cx.should_yield()||cx.is_cancelled()})||g.maximum_items==0||g.maximum_copy_bytes<bytes||g.maximum_depth==0{return Ok(false)}cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:bytes,..Default::default()})?;cx.consume_fuel(1);Ok(true)}
impl GuestRelayUnitFlow{
 pub fn empty()->Self{Self{binding:None,prepared:None,encoder:SourceJsonEncoder::new(),input:ManuallyDrop::new(None),input_close:None,phase:Phase::Encode,progress:ManuallyDrop::new(None),failure:ManuallyDrop::new(None),failure_close:None,cursor:0}}
 fn validate(&self,cx:&StepContext<'_>)->Result<(),OriginalTurnFailure>{cx.original_source_parent()?.validate_borrowed_context(cx)?;if self.binding.is_some_and(|b|!b.matches(cx)){return Err(refused().into())}Ok(())}
 /// 🔤️ The source is borrowed only in this slice; its complete or partial receiver stays in the original flow.
 pub fn encode_step<S:semio_framework_pack_json::JsonWriteSource+?Sized>(&mut self,source:&S,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if !matches!(self.phase,Phase::Encode|Phase::EncoderClose){return Err(refused().into())}if !metadata(cx,false)?{return Ok(false)}self.binding=Some(OriginalSourceBinding::borrow(cx));if self.phase==Phase::Encode{if self.encoder.advance(source,&mut*self.input,cx)?{self.phase=Phase::EncoderClose;}return Ok(false)}if self.encoder.close_step(cx)?{self.phase=Phase::Begin;return Ok(true)}Ok(false)}
 pub fn requires_execution(&self,runtime:&GuestRuntimes,instance:&GuestInstance)->Result<bool,OriginalTurnFailure>{if matches!(self.phase,Phase::Drive|Phase::Release){runtime.original_unit_requires_execution(instance)}else{Ok(false)}}
 pub fn needs_admission_budget(&self)->bool{self.phase==Phase::Begin}
 /// 🪙️ Controller metadata settles before the driver narrows its genuine VM credit from this actual context.
 pub fn prepare_execution_step(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;let retirement=cx.original_retirement_active();if self.failure().is_some()||!matches!(self.phase,Phase::Drive|Phase::Release)||retirement&&!matches!(self.phase,Phase::Drive|Phase::Release){return Err(refused().into())}let epoch=semio_framework_actor::RetainedTurnInput::borrow_original(cx)?.epoch;if self.prepared==Some(epoch){return Ok(true)}if !metadata(cx,retirement)?{return Ok(false)}self.progress.take();self.prepared=Some(epoch);Ok(true)}
 pub fn repeat_step(&mut self,runtime:&GuestRuntimes,instance:&mut GuestInstance,budget:semio_framework_actor::OriginalJobBudget,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if self.phase!=Phase::AwaitBudget||self.failure().is_some(){return Err(refused().into())}if cx.original_retirement_active()&&!budget.cancelled{return Err(refused().into())}if !metadata(cx,cx.original_retirement_active())?{return Ok(false)}self.progress.take();if runtime.repeat_original_unit_step(instance,budget,cx)?{self.phase=Phase::Drive;return Ok(true)}Ok(false)}
 pub fn execution_receipt(&self)->Option<OriginalGuestExecutionReceipt>{self.progress.as_ref().and_then(|reply|reply.execution)}
 pub fn progress(&self)->Option<&OwnedOriginalCallProgress>{self.progress.as_ref()}
 #[cfg(test)] pub(super) fn encoded(&self)->Option<&[u8]>{self.input.as_deref()}
 pub fn failure(&self)->Option<&OriginalTurnFailure>{self.failure.as_ref().or_else(||self.progress.as_ref().and_then(|reply|reply.result.as_ref().err()))}
 pub fn advance_step(&mut self,runtime:&GuestRuntimes,instance:&mut GuestInstance,budget:semio_framework_actor::OriginalJobBudget,execution:Option<OriginalGuestExecutionBudget>,cx:&mut StepContext<'_>)->Result<GuestRelayUnitStatus,OriginalTurnFailure>{self.advance(runtime,instance,budget,execution,cx)}
 fn advance(&mut self,runtime:&GuestRuntimes,instance:&mut GuestInstance,budget:semio_framework_actor::OriginalJobBudget,execution:Option<OriginalGuestExecutionBudget>,cx:&mut StepContext<'_>)->Result<GuestRelayUnitStatus,OriginalTurnFailure>{
  self.validate(cx)?;let retirement=cx.original_retirement_active();if retirement&&!matches!(self.phase,Phase::Output|Phase::Acknowledge|Phase::Release|Phase::DonorClose|Phase::Complete)&&self.phase!=Phase::Drive{return Err(refused().into())}if self.failure().is_some(){return Ok(GuestRelayUnitStatus::Refused)}if self.phase==Phase::AwaitBudget{return Ok(GuestRelayUnitStatus::AwaitBudget)}if self.phase==Phase::Complete{return Ok(GuestRelayUnitStatus::Complete)}if self.phase==Phase::Output{return Ok(GuestRelayUnitStatus::Output)}if execution.is_some(){if self.prepared!=Some(semio_framework_actor::RetainedTurnInput::borrow_original(cx)?.epoch){return Err(refused().into())}}else if !metadata(cx,retirement)?{return Ok(GuestRelayUnitStatus::Pending)}self.prepared=None;self.progress.take();
  match self.phase{Phase::Begin=>{if execution.is_some(){return Err(refused().into())}if runtime.begin_original_unit_step(instance,&mut*self.input,budget,cx)?{self.phase=Phase::Drive;}},Phase::Drive|Phase::Release=>{let release=self.phase==Phase::Release;let result=runtime.advance_original_unit_step(instance,execution,cx);match result{Ok(reply)=>{let status=reply.result.as_ref().ok().copied();*self.progress=Some(reply);match status{Some(OwnedOriginalCallStatus::Ready)=>self.phase=if release{Phase::DonorClose}else{Phase::Output},Some(OwnedOriginalCallStatus::Cancelled)=>*self.failure=Some(ValueError::literal(ValueRefusalKind::Canceled,"original unit observed cancellation").into()),Some(OwnedOriginalCallStatus::Deadline)=>*self.failure=Some(ValueError::literal(ValueRefusalKind::WorkLimit,"original unit reached its deadline").into()),_=>{}}},Err(error)=>*self.failure=Some(error)}},Phase::Acknowledge=>{if execution.is_some(){return Err(refused().into())}if runtime.acknowledge_original_unit_step(instance,cx)?{self.phase=Phase::Release;}},Phase::DonorClose=>{if execution.is_some(){return Err(refused().into())}if runtime.close_original_unit_step(instance,cx)?{self.phase=Phase::Complete;return Ok(GuestRelayUnitStatus::Complete)}},_=>return Err(refused().into())}if runtime.original_unit_waiting_for_budget(instance)?{self.phase=Phase::AwaitBudget;return Ok(GuestRelayUnitStatus::AwaitBudget)}Ok(if self.failure().is_some(){GuestRelayUnitStatus::Refused}else if self.phase==Phase::Output{GuestRelayUnitStatus::Output}else{GuestRelayUnitStatus::Pending})
 }
 /// 👁️ A fixed receipt or result is accepted before the same frozen guest memory can be released.
 pub fn receive_output_step(&mut self,runtime:&GuestRuntimes,instance:&GuestInstance,cx:&mut StepContext<'_>,receive:impl FnOnce(&[u8],&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if self.phase!=Phase::Output{return Err(refused().into())}let retirement=cx.original_retirement_active();if !metadata(cx,retirement)?{return Ok(false)}let mut accepted=false;if !runtime.with_original_unit_output(instance,cx,|bytes,cx|{accepted=receive(bytes,cx)?;Ok(())})?{return Err(refused().into())}if accepted{self.phase=Phase::Acknowledge;}Ok(accepted)}
 /// 📤️ A second original recipient receives actual frozen bytes without an escaped Vec.
 pub fn copy_output_step(&mut self,runtime:&GuestRuntimes,instance:&GuestInstance,output:&mut GuestRelayOutputHome,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{let mut cursor=self.cursor;let result=self.receive_output_step(runtime,instance,cx,|bytes,cx|{if !output.prepare(bytes.len(),cx)?{return Ok(false)}output.append_page(0,bytes,&mut cursor,cx)});self.cursor=cursor;result}
 pub fn take_failure_step(&mut self,cx:&mut StepContext<'_>,receive:impl FnOnce(&mut Option<OriginalTurnFailure>,&mut StepContext<'_>)->Result<(),OriginalTurnFailure>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if !metadata(cx,true)?{return Ok(false)}if self.failure.is_none(){if let Some(reply)=self.progress.take(){match reply.result{Err(error)=>*self.failure=Some(error),Ok(status)=>*self.progress=Some(OwnedOriginalCallProgress{result:Ok(status),execution:reply.execution})}}}if self.failure.is_none(){return Ok(false)}receive(&mut*self.failure,cx)?;Ok(self.failure.is_none())}
 pub fn close_step(&mut self,runtime:&GuestRuntimes,instance:&mut GuestInstance,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if runtime.original_unit_is_pending(instance)?&&!runtime.close_original_unit_step(instance,cx)?{return Ok(false)}self.close_unopened(cx)}
 pub fn close_unopened(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{
  self.validate(cx)?;if !metadata(cx,true)?{return Ok(false)}self.phase=Phase::Closing;if !self.encoder.terminal_is_empty(){self.encoder.close_step(cx)?;return Ok(false)}
  if let Some(reply)=self.progress.take(){if let Err(error)=reply.result{if self.failure_close.is_some(){*self.progress=Some(OwnedOriginalCallProgress{result:Err(error),execution:reply.execution});return Ok(false)}self.failure_close=Some(ControlledRetirement::retain(error));}return Ok(false)}
  if let Some(owner)=self.input_close.as_mut(){if !owner.terminal_is_empty(){let grant=cx.retained_grant();let body=grant.maximum_copy_bytes;let Some((poll,_))=cx.with_original_effect(grant,|_,effect|owner.step(body,effect))? else{return Ok(false)};let turn=match poll{semio_framework_value::RetainedWorkPoll::Complete(turn)=>turn,semio_framework_value::RetainedWorkPoll::Pending{work}=>semio_framework_value::RetainedWorkOutcome{result:Ok(semio_framework_value::RetainedCloneStep::Progress(Default::default())),work}};semio_framework_job::receive_original_retained_work(cx,turn)?;return Ok(false)}self.input_close.take();return Ok(false)}if let Some(owner)=self.failure_close.as_mut(){if !owner.terminal_is_empty(){let grant=cx.retained_grant();let body=grant.maximum_copy_bytes;let Some((poll,_))=cx.with_original_effect(grant,|_,effect|owner.step(body,effect))? else{return Ok(false)};let turn=match poll{semio_framework_value::RetainedWorkPoll::Complete(turn)=>turn,semio_framework_value::RetainedWorkPoll::Pending{work}=>semio_framework_value::RetainedWorkOutcome{result:Ok(semio_framework_value::RetainedCloneStep::Progress(Default::default())),work}};semio_framework_job::receive_original_retained_work(cx,turn)?;return Ok(false)}self.failure_close.take();return Ok(false)}
  if let Some(input)=self.input.take(){self.input_close=Some(ControlledRetirement::retain(input));return Ok(false)}if let Some(error)=self.failure.take(){self.failure_close=Some(ControlledRetirement::retain(error));return Ok(false)}self.prepared=None;self.cursor=0;self.phase=Phase::Complete;Ok(true)
 }
 pub fn terminal_is_empty(&self)->bool{self.encoder.terminal_is_empty()&&self.input.is_none()&&self.input_close.is_none()&&self.progress.is_none()&&self.failure.is_none()&&self.failure_close.is_none()}
}
impl Drop for GuestRelayUnitFlow{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original unit flow requires Source-funded owner retirement")}}
#[cfg(test)]
mod tests{
 use super::*;
 use semio_framework_job::{OriginalJobFixtureCaller,OperationId,Generation};
 use semio_framework_value::{DslValue,RetainedCloneGrant};
 fn clock()->Option<u64>{Some(1000)}

 #[test]
 fn original_unit_flow_retains_donor_before_instance_birth_and_retires_after_cancel(){let law:serde_json::Value=serde_json::from_str(include_str!("law.json")).unwrap();let view=DslValue::String(law["value"].as_str().unwrap().into());let grant=RetainedCloneGrant{maximum_items:10000,maximum_copy_bytes:4096,maximum_capacity_bytes:1<<20,maximum_release_bytes:1<<20,maximum_depth:64};let mut caller=OriginalJobFixtureCaller::admit(OperationId(792),Generation(1),grant,clock,1000000,1000000);let mut flow=GuestRelayUnitFlow::empty();let mut epoch=0;let(mut born,mut freed)=(0,0);for _ in 0..law["maximumSlices"].as_u64().unwrap(){epoch+=1;let(done,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn(grant,|cx|{cx.bind_original_source_epoch(epoch)?;flow.encode_step(&view,cx)}).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes));born+=heap.requested_bytes;freed+=heap.released_bytes;if done{break}}assert!(flow.phase==Phase::Begin);assert_eq!(flow.input.as_deref().unwrap(),law["wire"].as_str().unwrap().as_bytes());assert_eq!(serde_json::from_slice::<serde_json::Value>(flow.input.as_ref().unwrap()).unwrap(),law["value"]);let mut foreign=OriginalJobFixtureCaller::admit(OperationId(792),Generation(1),grant,clock,1000000,1000000);assert!(foreign.turn(grant,|cx|flow.close_unopened(cx)).is_err());assert_eq!(foreign.receipt(),Default::default());foreign.retire(grant);caller.cancel().cancel_now();for _ in 0..law["maximumSlices"].as_u64().unwrap(){epoch+=1;let(done,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn(grant,|cx|{cx.bind_original_source_epoch(epoch)?;cx.with_original_retirement(|cx|flow.close_unopened(cx))}).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes));born+=heap.requested_bytes;freed+=heap.released_bytes;if done{break}}assert!(flow.terminal_is_empty());assert_eq!(born,freed);assert_eq!(semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(flow)).1.released_bytes,0);caller.retire(grant);}
}
